118	///|
119	pub fn interpolate(
120	  value : String,
121	  lookup : (String) -> String?,
122	  location : String,
123	) -> String raise ConfigError {
124	  let output = StringBuilder()
125	  let mut remaining = value
126	  while remaining.split_once("${") is Some((prefix, expression)) {
127	    output.write_string(prefix.to_owned())
128	    guard expression.split_once("}") is Some((variable, suffix)) else {
129	      raise InvalidConfig("\{location}: unterminated environment variable")
130	    }
131	    let text = variable.to_owned()
132	    let required = text.has_suffix("?")
133	    let name = if required { text[:text.length() - 1].to_owned() } else { text }
134	    guard valid_env_name(name) else {
135	      raise InvalidConfig("\{location}: invalid environment variable reference")
136	    }
137	    match lookup(name) {
138	      Some(resolved) => output.write_string(resolved)
139	      None if required =>
140	        raise InvalidConfig(
141	          "\{location}: environment variable \{name} is not defined",
142	        )
143	      None => ()
144	    }
145	    remaining = suffix.to_owned()
146	  }
147	  output.write_string(remaining)
148	  output.to_string()
149	}
