 41	fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
 42	  let buffer = @buffer.Buffer(size_hint=end - start)
 43	  for i in start..<end {
 44	    buffer.write_char_utf8(chars[i])
 45	  }
 46	  @utf8.decode_lossy(buffer.to_bytes())
 47	}
