 51	  match c {
 52	    '0'..<='9' => Some(c.to_int() - '0'.to_int())
 53	    'a'..<='f' => Some(c.to_int() - 'a'.to_int() + 10)
 54	    'A'..<='F' => Some(c.to_int() - 'A'.to_int() + 10)
 55	    _ => None
