 63	  let mut i = 0
 64	  while i < chars.length() {
 65	    if chars[i] == '%' &&
 66	      i + 2 < chars.length() &&
 67	      credential_hex(chars[i + 1]) is Some(hi) &&
 68	      credential_hex(chars[i + 2]) is Some(lo) {
