   231	///|
   232	fn server_env_value(value : String, root : String) -> String raise {
   233	  let result = StringBuilder()
   234	  let mut remaining = value
   235	  while remaining.split_once("${") is Some((prefix, expression)) {
   236	    result.write_string(quote(prefix.to_owned()))
   237	    guard expression.split_once("}") is Some((variable, suffix)) else {
   238	      raise AdapterError("Invalid saved server environment reference")
   239	    }
   240	    let reference = variable.to_owned()
   241	    let required = reference.has_suffix("?")
   242	    let name = if required {
   243	      reference[:reference.length() - 1].to_owned()
   244	    } else {
   245	      reference
   246	    }
   247	    ignore(
   248	      interpolate("${" + reference + "}", _ => Some(""), "server environment"),
   249	    )
   250	    if name == "DEVSY_REMOTE_WORKSPACE_FOLDER" {
   251	      result.write_string(quote(root))
   252	    } else {
   253	      result.write_string(
   254	        "\"${" + name + (if required { "?" } else { "-" }) + "}\"",
   255	      )
   256	    }
   257	    remaining = suffix.to_owned()
   258	  }
   259	  result.write_string(quote(remaining))
   260	  result.to_string()
   261	}
