   103	///|
   104	fn valid_env_name(name : String) -> Bool {
   105	  let characters = name.to_array()
   106	  characters.length() > 0 &&
   107	  !(characters[0] >= '0' && characters[0] <= '9') &&
   108	  characters
   109	  .iter()
   110	  .all(char => {
   111	    char == '_' ||
   112	    (char >= 'a' && char <= 'z') ||
   113	    (char >= 'A' && char <= 'Z') ||
   114	    (char >= '0' && char <= '9')
   115	  })
   116	}
