275	///|
276	fn server_launch_script(
277	  root : String,
278	  port : Int32,
279	  server_env : Json,
280	) -> String raise {
281	  let assignments = StringBuilder()
282	  let exports = StringBuilder()
283	  if server_env is Json::Object(values) {
284	    for name, value in values {
285	      guard valid_env_name(name) else {
286	        raise AdapterError("Invalid saved server environment name")
287	      }
288	      ignore(
289	        interpolate("${" + name + "}", _ => Some(""), "server environment"),
290	      )
291	      guard value is Json::String(text) && !text.contains("\u0000") else {
292	        raise AdapterError("Invalid saved server environment")
293	      }
294	      assignments.write_string(" " + server_env_value(text, root))
295	      exports.write_string("export " + name + "=\"$1\"; shift; ")
296	    }
297	  } else {
298	    raise AdapterError("Invalid saved server environment")
299	  }
300	
301	  // The Linux wrapper in 1.4.224 resolves the app root inside app.asar.unpacked.
302	  // Invoke the package-declared CLI entry so Orca prepares its bundled orcad.
303	  (if assignments.to_string() == "" {
304	    ""
305	  } else {
306	    "set --" + assignments.to_string() + "; " + exports.to_string()
307	  }) +
308	  "ELECTRON_RUN_AS_NODE=1 exec" +
309	  " \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" \"$HOME/.local/share/orca-env-devsy/orca/current/resources/app.asar/out/cli/index.js\" serve --recipe-json --project-root " +
310	  quote(root) +
311	  " --port 47121 --pairing-address " +
312	  quote("ws://127.0.0.1:\{port}") +
313	  // A detached server must not retain the SSH channel's stderr pipe.
314	  " 2>/dev/null"
315	}
