   243	///|
   244	fn server_env_value(value : String, root : String) -> String raise {
   245	  let result = StringBuilder()
   246	  let mut remaining = value
   247	  while remaining.split_once("${") is Some((prefix, expression)) {
   248	    result.write_string(quote(prefix.to_owned()))
   249	    guard expression.split_once("}") is Some((variable, suffix)) else {
   250	      raise AdapterError("Invalid saved server environment reference")
   251	    }
   252	    let reference = variable.to_owned()
   253	    let required = reference.has_suffix("?")
   254	    let name = if required {
   255	      reference[:reference.length() - 1].to_owned()
   256	    } else {
   257	      reference
   258	    }
   259	    ignore(
   260	      interpolate("${" + reference + "}", _ => Some(""), "server environment"),
   261	    )
   262	    if name == "DEVSY_REMOTE_WORKSPACE_FOLDER" {
   263	      result.write_string(quote(root))
   264	    } else {
   265	      result.write_string(
   266	        "\"${" + name + (if required { "?" } else { "-" }) + "}\"",
   267	      )
   268	    }
   269	    remaining = suffix.to_owned()
   270	  }
   271	  result.write_string(quote(remaining))
   272	  result.to_string()
   273	}
